import numpy as np
from scipy.optimize import least_squares
t,x,v,y=df['t'].values,df['x'].values,df['v'].values,df['dv_dt'].values
def model(p):
    return p[0]*v**2 + p[1]*np.log(1+p[2]*x)*t + p[3]*np.exp(-p[4]*t**2)*v
best=None
for s in range(30):
    p0=np.random.RandomState(s).uniform(0.2,2,5)
    r=least_squares(lambda p: model(p)-y, p0, bounds=([-10,-10,0,-10,0],[10,10,10,10,10]))
    if best is None or r.cost<best.cost: best=r
res=y-model(best.x)
un={}
for nm,z in {'t':t,'x':x,'v':v}.items():
    un[f'sin({nm})']=np.sin(z); un[f'cos({nm})']=np.cos(z); un[f'exp(-{nm})']=np.exp(-z)
    un[f'{nm}']=z; un[f'{nm}^2']=z**2; un[f'log(1+{nm})']=np.log(1+z); un[f'exp(-{nm}^2)']=np.exp(-z**2)
    un[f'1/(1+{nm})']=1/(1+z)
ks=list(un)
out=[]
for a in ks:
    for b in ks:
        if a[-1]!=b[-1] and a<b and a.split('(')[-1][0]!=b.split('(')[-1][0]:
            pass
for a in ks:
    for b in ks:
        if a<b and a[-2:] not in [b[-2:]]:
            pass
import itertools
def inp(k):
    for nm in 'txv':
        if nm in k.replace('exp','').replace('sin','').replace('cos','').replace('log',''): return nm
    return None
